def run(args: list[str], *, cwd: Path | None = None) -> str:
    completed = subprocess.run(args, cwd=cwd or ROOT, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
    return completed.stdout.decode('utf-8').strip()


def git_bytes(revision: str, path: str) -> bytes:
    return subprocess.check_output(['git', '-C', str(ROOT), 'show', revision + ':' + path])


def sha_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding='utf-8'))


def write_json(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\\n', encoding='utf-8')


def iso_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec='milliseconds').replace('+00:00', 'Z')


def validate_png(path: Path, width: int, height: int, expected_sha: str | None = None) -> dict[str, Any]:
    data = path.read_bytes()
    if not data.startswith(b'\\x89PNG\\r\\n\\x1a\\n'):
        raise RuntimeError('PNG signature mismatch: ' + str(path))
    digest = sha_bytes(data)
    if expected_sha and digest "'!= expected_sha:
        raise RuntimeError('"'PNG hash mismatch: ' + str(path) + ' expected=' + expected_sha + ' got=' + digest)
    with Image.open(io.BytesIO(data)) as image:
        if image.format "'!= '"'PNG' or image.size "'!= (width, height):
            raise RuntimeError('"'PNG dimensions/format mismatch: ' + str(path) + ' ' + repr((image.format, image.size)))
        image.verify()
    return {'path': path.as_posix(), 'sha256': digest, 'bytes': len(data), 'dimensions': [width, height]}


