    if run(['git', 'branch', '--show-current']) "'!= '"'codex/sysgrid-visual-atlas-r4-evidence-reconcile-v1':
        raise RuntimeError('Unexpected Product work branch')
    if run(['git', 'status', '--porcelain=v1']):
